(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:''};
  async function api(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;const response=await fetch('../../../api/vendor/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Evidence request failed.');return data;}
  function status(text,error=false){el('vsi-status').textContent=text;el('vsi-status').className='vc-status '+(error?'warning':'info');}
  function cards(id,items,titleKey,statusKey,empty){const wrap=el(id);wrap.replaceChildren();if(!items.length){wrap.textContent=empty;return;}items.forEach(item=>{const row=document.createElement('div');row.className='vc-list-item';const copy=document.createElement('div');copy.className='vc-list-copy';const title=document.createElement('strong');title.textContent=item[titleKey];const detail=document.createElement('p');detail.textContent='Review: '+item[statusKey].replaceAll('_',' ')+' · File scan: '+item.scan_status+(item.valid_until?' · Valid until '+item.valid_until:'');copy.append(title,detail);row.append(copy);wrap.append(row);});}
  async function load(){try{const [identity,data]=await Promise.all([api('auth/me.php'),api('sustainability.php')]);state.csrf=identity.csrf_token||'';cards('vsi-claims',data.claims||[],'claim_statement','review_status','No claims submitted yet.');cards('vsi-certificates',data.certificates||[],'certificate_type','verification_status','No certificates uploaded yet.');status((data.claims||[]).length+' claims · '+(data.certificates||[]).length+' certificates');}catch(error){status(error.message,true);}}
  ['vsi-claim','vsi-certificate'].forEach(id=>el(id).addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const file=form.elements.namedItem('evidence').files[0];if(!file||file.size<1||file.size>10*1024*1024||!['application/pdf','image/jpeg','image/png'].includes(file.type)){status('Choose a PDF, JPEG, or PNG under 10 MB.',true);return;}const body=new FormData(form);body.set('record_type',id==='vsi-certificate'?'certificate':'claim');const button=event.submitter;button.disabled=true;try{await api('sustainability.php','POST',body);form.reset();await load();status('Evidence submitted for review.');}catch(error){status(error.message,true);}finally{button.disabled=false;}}));
  load();
})();
